import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { ArrowUpRight, ArrowRight, ArrowLeft, ChevronRight, ChevronDown, X, Search, Bell, Settings, HelpCircle, LayoutDashboard, MessagesSquare, ChartNoAxesCombined, BookOpen, Target, Clock3, Flame, Sparkles, Check, CheckCheck, Send, RotateCcw, Flag, Menu, MoreHorizontal, BriefcaseBusiness, HeartHandshake, Handshake, ShieldCheck, Users, Wallet, Building2, ShoppingBag, Headphones, House, Lightbulb, Compass, TrendingUp, GraduationCap, CircleCheck, CircleDashed, Download, Trash2, ExternalLink, AlertCircle, Info, Pause, Play, NotebookPen, Quote, MoveUpRight, Plus, Minus, CheckCircle2, Route, Ear, SlidersHorizontal, FileCheck2 } from 'lucide-react';
import { scenarios, categories, levelNames, skills, lessons } from './data.js';
import { createSession, advance, finishSession, rewind, suggestions, evaluate, feedbackFor, intentLabels, normalize } from './engine.js';
import { readStore, writeStore, emptyStore, downloadFile } from './storage.js';
import { dateKey, dateLabel, weekStartKey } from './dates.js';

const iconMap = { salary: Wallet, client: Headphones, boundary: ShieldCheck, interview: BriefcaseBusiness, sale: ShoppingBag, team: Users, priority: Target, supplier: Building2, deal: Handshake, conflict: MessagesSquare, home: House, feedback: HeartHandshake, search: Search, route: Route, ear: Ear, exchange: Handshake, shield: ShieldCheck, timer: Clock3, check: FileCheck2, chart: TrendingUp };
const navItems = [{ id: 'home', label: 'Mi entrenamiento', icon: LayoutDashboard }, { id: 'scenarios', label: 'Simulaciones', icon: MessagesSquare }, { id: 'progress', label: 'Mi progreso', icon: ChartNoAxesCombined }, { id: 'library', label: 'Biblioteca', icon: BookOpen }];
const skillDescriptions = { clarity: 'Argumentos concretos y propuestas comprensibles.', listening: 'Preguntas y comprobación de intereses.', empathy: 'Reconocimiento de la experiencia del otro.', assertiveness: 'Límites e intercambios expresados con respeto.', preparation: 'Objetivo, alternativa y límite preparados antes de hablar.', strategy: 'Exploración de intereses e intercambios condicionados.', emotion: 'Respeto y reparación ante la tensión.', creativity: 'Opciones que combinan distintas variables.', agreement: 'Condiciones concretas y confirmación del resultado.' };

function Logo({ small = false }) {
  return <div className={`brand ${small ? 'small' : ''}`}><svg width="34" height="36" viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M5 4h14a11 11 0 0 1 0 22h-4V14H5z" fill="currentColor"/><path d="M5 19h8v13H5z" fill="currentColor" opacity=".46"/></svg>{!small && <span>pacto<span className="brand-dot">.</span></span>}</div>;
}

function HeroArt() {
  return <div className="hero-art" aria-hidden="true"><svg viewBox="0 0 380 260" fill="none"><defs><radialGradient id="orb"><stop stopColor="#ded6ff"/><stop offset=".5" stopColor="#a491ef"/><stop offset="1" stopColor="#6650af"/></radialGradient><linearGradient id="ring" x1="55" y1="50" x2="320" y2="220" gradientUnits="userSpaceOnUse"><stop stopColor="#eee9ff"/><stop offset=".45" stopColor="#c9b5ff"/><stop offset="1" stopColor="#7862ad"/></linearGradient><linearGradient id="mint" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#daffea"/><stop offset="1" stopColor="#8bbdaa"/></linearGradient><filter id="shadow"><feGaussianBlur stdDeviation="10"/></filter></defs><ellipse cx="194" cy="224" rx="102" ry="12" fill="#130c2d" opacity=".45" filter="url(#shadow)"/><ellipse cx="196" cy="125" rx="136" ry="48" transform="rotate(-35 196 125)" stroke="#b7a0ee" strokeWidth="1" opacity=".22"/><ellipse cx="196" cy="125" rx="116" ry="55" transform="rotate(30 196 125)" stroke="url(#ring)" strokeWidth="22"/><circle cx="196" cy="125" r="65" fill="url(#orb)"/><path d="M88 91c-14 23 22 63 82 89s122 26 138 4" stroke="url(#ring)" strokeWidth="22" strokeLinecap="round"/><circle cx="298" cy="61" r="19" fill="url(#mint)"/><circle cx="79" cy="175" r="10" fill="#c7b7f5"/><path d="m82 48 3 9 9 3-9 3-3 9-3-9-9-3 9-3 3-9Z" fill="#d2c5ff"/><path d="m315 186 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6Z" fill="#bfa9f1"/><circle cx="138" cy="36" r="2" fill="#d6c5ff"/><circle cx="333" cy="135" r="2" fill="#d6c5ff"/></svg><div className="art-note"><span className="live-dot"/> Pequeñas prácticas. Grandes cambios.</div></div>;
}

function CaseArt({ scenario }) {
  const Icon = iconMap[scenario.icon];
  return <div className={`case-art ${scenario.color}`} aria-hidden="true"><div className="art-grid"/><span className="art-circle circle-one"/><span className="art-circle circle-two"/><div className="case-object"><Icon size={38} strokeWidth={1.4}/><span className="object-dot"><Check size={12}/></span></div><span className="art-dash dash-one"/><span className="art-dash dash-two"/><svg className="case-spark" width="24" height="24" viewBox="0 0 24 24"><path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z" fill="currentColor"/></svg></div>;
}

function Avatar({ person, size = '' }) {
  return <div className={`avatar avatar-${person.avatar} ${size}`} aria-label={person.name}><span>{person.initials}</span><span className="avatar-shine"/></div>;
}

function LevelBadge({ level }) {
  return <span className={`level-badge level-${level}`}><span className="level-bars">{[1, 2, 3].map(n => <i key={n} className={n <= level ? 'filled' : ''}/>)}</span>{levelNames[level]}</span>;
}

function ScenarioCard({ scenario, onSelect, completed }) {
  return <button className="scenario-card" onClick={() => onSelect(scenario)}>
    <div className="card-art-wrap"><CaseArt scenario={scenario}/>{scenario.tag && <span className="card-label">{scenario.tag}</span>}{completed && <span className="completed-badge" title="Ya practicaste este caso"><Check size={13}/> Practicado</span>}</div>
    <div className="scenario-card-body"><div className="card-meta"><span>{scenario.category}</span><span><Clock3 size={12}/>{scenario.minutes} min</span></div><h3>{scenario.title}</h3><p>{scenario.description}</p><div className="card-footer"><LevelBadge level={scenario.level}/><span className="start-case">Entrenar <ArrowUpRight size={16}/></span></div></div>
  </button>;
}

function Modal({ children, onClose, className = '', titleId }) {
  const ref = useRef();
  const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const before = document.activeElement;
    document.body.style.overflow = 'hidden';
    const background = document.querySelectorAll('.main-shell, .sidebar');
    background.forEach(el => el.inert = true);
    ref.current?.focus();
    const handler = e => {
      if (e.key === 'Escape') closeRef.current();
      if (e.key === 'Tab') {
        const targets = [...ref.current.querySelectorAll('button, a, input, textarea, select, [tabindex="0"]')].filter(el => !el.disabled);
        const first = targets[0], last = targets.at(-1);
        if (e.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { e.preventDefault(); last?.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
      }
    };
    document.addEventListener('keydown', handler);
    return () => { document.body.style.overflow = ''; background.forEach(el => el.inert = false); document.removeEventListener('keydown', handler); before?.focus(); };
  }, []);
  return createPortal(<div className="modal-backdrop" onClick={e => e.target === e.currentTarget && onClose()}><section ref={ref} tabIndex={-1} role="dialog" aria-modal="true" aria-labelledby={titleId} className={`modal ${className}`}><button className="icon-button modal-close" aria-label="Cerrar" onClick={onClose}><X size={20}/></button>{children}</section></div>, document.body);
}

function PrepareModal({ scenario, onClose, onStart, hasActive }) {
  const [notes, setNotes] = useState({ objective: '', alternative: '', limit: '' });
  const [step, setStep] = useState(0);
  return <Modal onClose={onClose} className="prepare-modal" titleId="prepare-title">
    <div className="prepare-heading"><span className="eyebrow">ANTES DE LA CONVERSACIÓN</span><h2 id="prepare-title">{scenario.title}</h2><p>{scenario.subtitle}</p><div className="prepare-meta"><LevelBadge level={scenario.level}/><span><Clock3 size={14}/>{scenario.minutes} min</span><span><MessagesSquare size={14}/>Hasta 12 intervenciones</span></div></div>
    <div className="step-tabs"><button onClick={() => setStep(0)} className={step === 0 ? 'active' : ''}><span>1</span> Conoce el caso</button><button onClick={() => setStep(1)} className={step === 1 ? 'active' : ''}><span>2</span> Prepara tu estrategia</button></div>
    {step === 0 ? <div className="case-brief"><div className="brief-main"><h3>Estás en esta situación</h3><p>{scenario.context}</p><div className="objective-box"><Target size={20}/><div><h4>Tu objetivo de práctica</h4><p>{scenario.objective}</p></div></div><h3>Lo que sabes</h3><ul className="check-list">{scenario.facts.map(f => <li key={f}><Check size={15}/>{f}</li>)}</ul><h3>Restricciones reales</h3><ul className="constraint-list">{scenario.constraints.map(f => <li key={f}>{f}</li>)}</ul></div><aside className="brief-aside"><Avatar person={scenario.person} size="large"/><h3>{scenario.person.name}</h3><p>{scenario.person.role}</p><span className="person-style">{scenario.person.style}</span><hr/><h4>Qué le importa</h4><p>{scenario.person.motivation}</p><h4>Tus intereses</h4><ul>{scenario.interests.map(f => <li key={f}>{f}</li>)}</ul></aside></div> : <div className="preparation-form"><div className="inline-note"><NotebookPen size={21}/><p>Un minuto de preparación cambia la conversación. Estas notas son privadas y estarán disponibles mientras practicas.</p></div>{[['objective', '¿Qué quieres conseguir?', scenario.objective], ['alternative', '¿Qué harás si no hay acuerdo?', scenario.starter], ['limit', '¿Qué límite no quieres cruzar?', scenario.constraints[0]]].map(([key, label, placeholder]) => <label key={key}>{label}<textarea maxLength={600} value={notes[key]} onChange={e => setNotes({ ...notes, [key]: e.target.value })} placeholder={placeholder} rows={2}/></label>)}<p className="muted small-text">Puedes comenzar sin completar las notas. La revisión distinguirá lo que preparaste de lo que observó en el diálogo.</p></div>}
    <div className="modal-footer"><span className="muted small-text"><ShieldCheck size={15}/> Un espacio seguro para equivocarte</span>{step === 0 ? <button className="button primary" onClick={() => setStep(1)}>Preparar mi estrategia <ArrowRight size={16}/></button> : <button className="button primary" onClick={() => onStart(scenario, notes)}>{hasActive ? 'Guardar la pausa e iniciar este caso' : 'Comenzar simulación'}<ArrowRight size={16}/></button>}</div>
    {hasActive && <p className="active-warning">Tienes una práctica en pausa. Al iniciar esta, la anterior se guardará en tu historial como finalizada sin acuerdo.</p>}
  </Modal>;
}

function App() {
  const [store, setStore] = useState(readStore);
  const [page, setPage] = useState('home');
  const [category, setCategory] = useState('Todos');
  const [query, setQuery] = useState('');
  const [level, setLevel] = useState('all');
  const [sort, setSort] = useState('recommended');
  const [selected, setSelected] = useState(null);
  const [lesson, setLesson] = useState(null);
  const [settings, setSettings] = useState(false);
  const [help, setHelp] = useState(false);
  const [notifications, setNotifications] = useState(false);
  const [sidebar, setSidebar] = useState(false);
  const [review, setReview] = useState(null);
  const [toast, setToast] = useState('');
  const [storageWarning, setStorageWarning] = useState(false);
  const [tip, setTip] = useState(0);
  const searchRef = useRef();
  const history = store.history.filter(s => scenarios.some(c => c.id === s.scenarioId));
  const evaluations = useMemo(() => history.map(evaluate), [store.history]);
  const completedIds = new Set(history.map(s => s.scenarioId));
  const averages = Object.fromEntries(skills.map(([k]) => [k, evaluations.length ? Math.round(evaluations.reduce((sum, e) => sum + e.scores[k], 0) / evaluations.length) : 0]));
  const strongest = skills.slice().sort((a, b) => averages[b[0]] - averages[a[0]])[0];
  const weakest = skills.filter(([key]) => key !== 'agreement').slice().sort((a, b) => averages[a[0]] - averages[b[0]])[0];
  const monday = weekStartKey();
  const weeklyCount = history.filter(s => dateKey(s.finishedAt) >= monday).length;
  const currentScenario = scenarios.find(s => s.id === store.active?.scenarioId);
  const filtered = scenarios.filter(s => (category === 'Todos' || category === s.category) && (level === 'all' || s.level === Number(level)) && normalize(`${s.title} ${s.subtitle} ${s.description} ${s.practice.join(' ')}`).includes(normalize(query)));
  if (sort === 'short') filtered.sort((a, b) => a.minutes - b.minutes);
  if (sort === 'level') filtered.sort((a, b) => a.level - b.level);
  if (sort === 'unplayed') filtered.sort((a, b) => Number(completedIds.has(a.id)) - Number(completedIds.has(b.id)));

  useEffect(() => { setStorageWarning(!writeStore(store)); }, [store]);
  useEffect(() => { if (toast) { const timeout = setTimeout(() => setToast(''), 4500); return () => clearTimeout(timeout); } }, [toast]);
  useEffect(() => { const handler = e => { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); searchRef.current?.focus(); } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler); }, []);
  useEffect(() => { window.scrollTo({ top: 0 }); setSidebar(false); setNotifications(false); }, [page]);
  const navigate = p => { setPage(p); setQuery(''); setCategory('Todos'); };
  const start = (scenario, preparation) => {
    const active = createSession(scenario, preparation);
    setStore(prev => ({ ...prev, active, history: prev.active?.turn > 0 ? [...prev.history, finishSession(prev.active)] : prev.history }));
    setSelected(null); setPage('session');
  };
  const updateSession = next => {
    if (next.status === 'finished') {
      setStore(prev => ({ ...prev, active: null, history: [...prev.history.filter(s => s.id !== next.id), next] }));
      setReview(next); setPage('review');
    } else setStore(prev => ({ ...prev, active: next }));
  };
  const openReview = session => { setReview(session); setPage('review'); };
  const recommended = history.length ? scenarios.find(s => s.practice.some(p => normalize(p).includes(normalize(weakest[1].split(' ')[0]))) && !completedIds.has(s.id)) || scenarios.find(s => !completedIds.has(s.id)) || scenarios[7] : scenarios[0];

  return <div className="app-shell">
    {sidebar && <div className="sidebar-scrim" onClick={() => setSidebar(false)}/>}
    <aside className={`sidebar ${sidebar ? 'open' : ''}`}><button className="logo-button" onClick={() => navigate('home')} aria-label="Pacto, inicio"><Logo/></button><div className="sidebar-label">TU ESPACIO DE PRÁCTICA</div><nav aria-label="Navegación principal">{navItems.map(item => <button className={`nav-item ${page === item.id || (item.id === 'scenarios' && page === 'session') ? 'active' : ''}`} onClick={() => navigate(item.id)} key={item.id}><item.icon size={19}/><span>{item.label}</span>{item.id === 'scenarios' && <span className="nav-count">12</span>}{page === item.id && <span className="nav-active-dot"/>}</button>)}</nav>
      <div className="sidebar-journey"><div className="journey-icon"><SproutIcon/></div><h4>La confianza se entrena</h4><p>Una conversación a la vez.<br/>A tu ritmo, con intención.</p><div className="journey-progress"><span style={{ width: `${Math.min(100, completedIds.size / 12 * 100)}%` }}/></div><div className="journey-caption"><span>Tu recorrido</span><b>{completedIds.size} / 12</b></div><button onClick={() => navigate('progress')}>Ver mi evolución <ArrowUpRight size={14}/></button></div>
      <div className="sidebar-bottom"><button onClick={() => setHelp(true)}><HelpCircle size={18}/>Ayuda y cómo funciona</button><button onClick={() => setSettings(true)}><Settings size={18}/>Configuración</button><div className="sidebar-profile"><span className="user-avatar">{store.name.charAt(0).toUpperCase()}</span><div><b>{store.name}</b><span>Tu espacio personal</span></div><button className="icon-button" onClick={() => setSettings(true)} aria-label="Editar perfil"><MoreHorizontal size={19}/></button></div></div>
    </aside>
    <div className="main-shell"><header className="topbar"><div className="topbar-location"><button className="icon-button mobile-menu" aria-label="Abrir menú" onClick={() => setSidebar(true)}><Menu size={22}/></button><span className="topbar-home"><House size={15}/></span><ChevronRight size={13}/><span>{page === 'session' ? 'Sala de práctica' : page === 'review' ? 'Tu análisis' : navItems.find(n => n.id === page)?.label}</span></div><div className="topbar-actions"><div className="global-search"><Search size={16}/><input ref={searchRef} aria-label="Buscar simulaciones" placeholder="Busca tu próxima conversación" value={query} onChange={e => { setQuery(e.target.value); setPage('scenarios'); }}/><kbd>⌘ K</kbd></div><div className="notification-wrap"><button className="icon-button notification-button" aria-label="Ver novedades" aria-expanded={notifications} onClick={() => setNotifications(!notifications)}><Bell size={19}/><i/></button>{notifications && <div className="notification-panel"><b>Tu próximo paso</b><p>{store.active ? 'Tienes una conversación en pausa. Puedes retomarla cuando quieras.' : `Esta semana has completado ${weeklyCount} de ${store.weeklyGoal} prácticas. Un pequeño paso también cuenta.`}</p><button className="text-link" onClick={() => { setNotifications(false); store.active ? setPage('session') : setSelected(recommended); }}>{store.active ? 'Retomar conversación' : 'Elegir una práctica'}<ArrowRight size={14}/></button></div>}</div><button className="user-avatar top-avatar" onClick={() => setSettings(true)} aria-label="Abrir mi perfil">{store.name.charAt(0).toUpperCase()}</button></div></header>
    {storageWarning && <div className="storage-warning" role="alert"><AlertCircle size={16}/> No se pudo guardar en este navegador. Puedes seguir practicando y exportar tu progreso desde Configuración.</div>}
    <main className={`main-content ${page === 'session' ? 'session-main' : ''}`}>
      {page === 'home' && <>
        <div className="page-heading"><div><div className="eyebrow">APRENDE HACIENDO. CONVERSA MEJOR.</div><h1>Tu próxima conversación<br className="mobile-br"/> puede cambiarlo todo<span className="purple-text">.</span></h1><p>Entrena hoy las habilidades que harán la diferencia mañana.</p></div><div className="greeting"><span className="greeting-dot"/> Tu espacio, {store.name}</div></div>
        {store.active && currentScenario && <div className="resume-banner"><div><Pause size={18}/><span>Dejaste una conversación en pausa: <b>{currentScenario.title}</b></span></div><button onClick={() => setPage('session')}>Retomar <ArrowRight size={16}/></button></div>}
        <section className="hero"><div className="hero-content"><span className="hero-eyebrow"><span/> UN ESPACIO PARA ENCONTRAR TU VOZ</span><h2>La confianza no se improvisa. <br/>Se practica.</h2><p>Conversaciones reales. Decisiones que importan.<br/>Un lugar seguro para probar, aprender y crecer.</p><button className="button hero-button" onClick={() => setSelected(recommended)}>{history.length ? 'Mi próxima práctica' : 'Comenzar mi primera práctica'}<ArrowUpRight size={17}/></button><span className="hero-footnote"><Clock3 size={12}/> Unos minutos hoy. Una habilidad para siempre.</span></div><HeroArt/></section>
        <div className="stats-grid"><StatCard icon={MessagesSquare} color="purple" value={history.length} label="Conversaciones practicadas" detail={history.length ? `${completedIds.size} escenarios diferentes explorados` : 'Tu primera conversación te espera'}/><StatCard icon={TrendingUp} color="mint" value={history.length ? strongest[1] : 'Por descubrir'} label="Tu fortaleza en desarrollo" detail={history.length ? 'Según tus intervenciones observadas' : 'Cada práctica te ayuda a conocerte'}/><div className="stat-card"><div className="stat-top"><span className="stat-icon peach"><Target size={19}/></span><span className="stat-detail-tag">ESTA SEMANA</span></div><div className="goal-stat"><strong>{weeklyCount}<span> / {store.weeklyGoal}</span></strong><div className="goal-dots">{Array.from({ length: store.weeklyGoal }, (_, i) => <span className={i < weeklyCount ? 'done' : ''} key={i}>{i < weeklyCount ? <Check size={12}/> : ''}</span>)}</div></div><h3>Tu objetivo de práctica</h3><p>{weeklyCount >= store.weeklyGoal ? '¡Objetivo cumplido! Sigue a tu ritmo.' : 'La constancia hace la diferencia'}</p></div></div>
        <section className="scenario-section"><div className="section-heading"><div><div className="section-eyebrow">DEL CONOCIMIENTO A LA ACCIÓN</div><h2>¿Qué conversación quieres entrenar?</h2><p>Situaciones de la vida real. Un mundo de formas de abordarlas.</p></div><button className="text-link" onClick={() => navigate('scenarios')}>Ver todas las simulaciones<ArrowRight size={16}/></button></div><div className="category-tabs" aria-label="Categorías">{categories.map((c, i) => { const Icon = [Compass, BriefcaseBusiness, Handshake, MessagesSquare, HeartHandshake][i]; return <button className={category === c ? 'active' : ''} key={c} onClick={() => setCategory(c)}><Icon size={15}/>{c}</button>; })}</div><div className="scenario-grid">{scenarios.filter(s => category === 'Todos' || s.category === category).slice(0, 3).map(s => <ScenarioCard key={s.id} scenario={s} onSelect={setSelected} completed={completedIds.has(s.id)}/>)}</div></section>
        <div className="home-bottom"><section className="daily-insight"><div className="insight-icon"><Lightbulb size={21}/></div><div><div className="section-eyebrow">UNA IDEA PARA TU PRÓXIMA CONVERSACIÓN</div><h3>{lessons[tip].title}</h3><p>{lessons[tip].short}</p><button className="text-link" onClick={() => setLesson(lessons[tip])}>Llévalo a la práctica <ArrowRight size={14}/></button></div><div className="insight-pagination"><button aria-label="Consejo anterior" onClick={() => setTip((tip + lessons.length - 1) % lessons.length)}><ChevronRight size={15} style={{ transform: 'rotate(180deg)' }}/></button><button aria-label="Siguiente consejo" onClick={() => setTip((tip + 1) % lessons.length)}><ChevronRight size={15}/></button></div></section><button className="library-promo" onClick={() => navigate('library')}><div className="library-icon"><BookOpen size={24}/></div><div><h3>Las herramientas detrás de<br/>una buena conversación.</h3><span>Explora la biblioteca <ArrowUpRight size={14}/></span></div></button></div>
        <Footer/>
      </>}
      {page === 'scenarios' && <><div className="page-heading"><div><div className="eyebrow">TU LABORATORIO DE CONVERSACIONES</div><h1>Practica para lo que viene<span className="purple-text">.</span></h1><p>Prueba nuevas estrategias, explora alternativas y encuentra tu forma de negociar.</p></div><span className="count-chip">12 situaciones reales</span></div><div className="explore-intro"><Compass size={23}/><div><b>{history.length ? 'Tu siguiente desafío está aquí' : 'Empieza por lo cotidiano. Crece desde ahí.'}</b><p>Todos los niveles están disponibles. Los casos iniciales son una buena primera parada.</p></div></div><div className="category-tabs">{categories.map(c => <button key={c} className={category === c ? 'active' : ''} onClick={() => setCategory(c)}>{c}</button>)}</div><div className="filter-row"><span>{filtered.length} {filtered.length === 1 ? 'simulación' : 'simulaciones'}{query && <> para «{query}» <button className="text-link" onClick={() => setQuery('')}>Limpiar</button></>}</span><div><label><SlidersHorizontal size={14}/><select aria-label="Filtrar por dificultad" value={level} onChange={e => setLevel(e.target.value)}><option value="all">Todos los niveles</option>{[1, 2, 3].map(n => <option key={n} value={n}>{levelNames[n]}</option>)}</select></label><label><select aria-label="Ordenar simulaciones" value={sort} onChange={e => setSort(e.target.value)}><option value="recommended">Recomendadas</option><option value="short">Menor duración</option><option value="level">Por dificultad</option><option value="unplayed">Sin practicar primero</option></select></label></div></div>{filtered.length ? <div className="scenario-grid explore-grid">{filtered.map(s => <ScenarioCard key={s.id} scenario={s} onSelect={setSelected} completed={completedIds.has(s.id)}/>)}</div> : <EmptyState icon={Search} title="Busquemos otra conversación" text="No hay casos con esa combinación. Prueba otra palabra o elimina los filtros." action="Restablecer filtros" onAction={() => { setQuery(''); setCategory('Todos'); setLevel('all'); }}/>}<Footer/></>}
      {page === 'library' && <Library completed={store.completedLessons} onOpen={setLesson}/>}
      {page === 'progress' && <Progress history={history} evaluations={evaluations} averages={averages} weeklyCount={weeklyCount} goal={store.weeklyGoal} onPractice={() => setSelected(recommended)} onReview={openReview} onLesson={setLesson} weakest={weakest}/>}
      {page === 'session' && (store.active && currentScenario ? <Session session={store.active} scenario={currentScenario} onUpdate={updateSession} onPause={() => { setPage('home'); setToast('Conversación guardada. Puedes retomarla cuando quieras.'); }} onHelp={() => setHelp(true)}/> : <EmptyState icon={MessagesSquare} title="Tu próxima conversación te espera" text="Elige una situación y entra en la sala de práctica." action="Explorar simulaciones" onAction={() => navigate('scenarios')}/>)}
      {page === 'review' && review && <Review session={review} scenario={scenarios.find(s => s.id === review.scenarioId)} onRetry={() => setSelected(scenarios.find(s => s.id === review.scenarioId))} onRewind={turn => { const scenario = scenarios.find(s => s.id === review.scenarioId); const next = rewind(review, scenario, turn); setStore(prev => ({ ...prev, active: next, history: prev.active?.turn > 0 ? [...prev.history, finishSession(prev.active)] : prev.history })); setPage('session'); }} onProgress={() => navigate('progress')} onLesson={setLesson}/>}
    </main></div>
    {selected && <PrepareModal scenario={selected} onClose={() => setSelected(null)} onStart={start} hasActive={!!store.active}/>}
    {lesson && <LessonModal lesson={lesson} completed={store.completedLessons.includes(lesson.id)} onClose={() => setLesson(null)} onComplete={() => { setStore(prev => ({ ...prev, completedLessons: [...new Set([...prev.completedLessons, lesson.id])] })); setToast('Lección guardada como leída. Ahora, llévala a una conversación.'); }} onPractice={() => { const next = scenarios.find(s => s.id === lesson.scenario); setLesson(null); setSelected(next); }}/>}
    {settings && <SettingsModal store={store} onUpdate={setStore} onReset={() => { setStore({ ...emptyStore, history: [], completedLessons: [] }); setReview(null); setPage('home'); }} onClose={() => setSettings(false)} onToast={setToast}/>}
    {help && <HelpModal onClose={() => setHelp(false)}/>}
    {toast && <div className="toast" role="status"><CircleCheck size={18}/>{toast}<button aria-label="Cerrar notificación" onClick={() => setToast('')}><X size={15}/></button></div>}
  </div>;
}

function SproutIcon() { return <svg width="30" height="30" viewBox="0 0 30 30" fill="none"><path d="M15 25V13m0 5C6 18 4 12 5 7c7 0 11 3 10 11Zm0-5c0-7 5-10 11-9 0 7-5 11-11 9Z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>; }
function StatCard({ icon: Icon, color, value, label, detail }) { return <div className="stat-card"><div className="stat-top"><span className={`stat-icon ${color}`}><Icon size={19}/></span><ArrowUpRight size={15} className="muted"/></div><strong className={typeof value === 'string' ? 'text-stat' : ''}>{value}</strong><h3>{label}</h3><p>{detail}</p></div>; }
function Footer() { return <footer className="page-footer"><span><Logo small/> Un espacio para conversar mejor.</span><span>Práctica con intención. Crece a tu ritmo.</span></footer>; }
function EmptyState({ icon: Icon, title, text, action, onAction }) { return <div className="empty-state"><div><Icon size={38} strokeWidth={1.4}/></div><h2>{title}</h2><p>{text}</p><button className="button primary" onClick={onAction}>{action}<ArrowRight size={16}/></button></div>; }

function Library({ completed, onOpen }) {
  const [filter, setFilter] = useState('Todos');
  return <><div className="page-heading"><div><div className="eyebrow">IDEAS QUE SE CONVIERTEN EN HABILIDADES</div><h1>Tu caja de herramientas<span className="purple-text">.</span></h1><p>Conceptos claros, ejemplos concretos y una forma de practicarlos hoy.</p></div><span className="count-chip"><BookOpen size={15}/>{completed.length} de {lessons.length} lecciones leídas</span></div><div className="library-feature"><div className="library-feature-art"><BookOpen size={64} strokeWidth={1}/><Sparkles size={22}/></div><div><span className="eyebrow">EL FUNDAMENTO DE UN BUEN ACUERDO</span><h2>Haz mejores preguntas.<br/>Descubre mejores opciones.</h2><p>Empieza por entender qué hay detrás de lo que la otra persona pide.</p><button className="button primary" onClick={() => onOpen(lessons[0])}>Explorar los intereses<ArrowUpRight size={16}/></button></div></div><div className="category-tabs">{['Todos', 'Fundamentos', 'Preparación', 'Comunicación', 'Estrategia'].map(c => <button key={c} className={filter === c ? 'active' : ''} onClick={() => setFilter(c)}>{c}</button>)}</div><div className="lesson-grid">{lessons.filter(l => filter === 'Todos' || l.category === filter).map(l => { const Icon = iconMap[l.icon]; return <button key={l.id} className="lesson-card" onClick={() => onOpen(l)}><div className="lesson-card-top"><span className="lesson-icon"><Icon size={22}/></span>{completed.includes(l.id) ? <span className="read-badge"><Check size={13}/>Leída</span> : <span className="muted small-text">{l.time} min de lectura</span>}</div><span className="section-eyebrow">{l.category}</span><h3>{l.title}</h3><p>{l.short}</p><span className="text-link">Aprender y practicar<ArrowUpRight size={15}/></span></button>; })}</div><Footer/></>;
}

function LessonModal({ lesson, completed, onClose, onComplete, onPractice }) {
  const Icon = iconMap[lesson.icon];
  return <Modal onClose={onClose} className="lesson-modal" titleId="lesson-title"><div className="lesson-heading"><span className="lesson-icon"><Icon size={25}/></span><div className="eyebrow">{lesson.category} · {lesson.time} MIN DE LECTURA</div><h2 id="lesson-title">{lesson.title}</h2><p>{lesson.short}</p></div><div className="lesson-content"><p>{lesson.intro}</p><blockquote><Quote size={22}/>{lesson.principle}</blockquote><h3>Así se ve en una conversación</h3><div className="example before"><span>UNA INTERVENCIÓN POR MEJORAR</span><p>«{lesson.example.before}»</p></div><div className="example after"><span>UNA ALTERNATIVA MÁS ÚTIL</span><p>«{lesson.example.after}»</p></div><h3>Pruébalo en tres pasos</h3><ol className="lesson-steps">{lesson.steps.map((s, i) => <li key={s}><span>{i + 1}</span>{s}</li>)}</ol><div className="exercise"><Target size={22}/><div><h4>Tu siguiente pequeño reto</h4><p>{lesson.exercise}</p></div></div></div><div className="modal-footer"><button className={`button ${completed ? 'completed-button' : 'secondary'}`} disabled={completed} onClick={onComplete}><Check size={16}/>{completed ? 'Lección leída' : 'Marcar como leída'}</button><button className="button primary" onClick={onPractice}>Practicar este concepto<ArrowRight size={16}/></button></div></Modal>;
}

function Session({ session, scenario, onUpdate, onPause, onHelp }) {
  const [text, setText] = useState('');
  const [thinking, setThinking] = useState(false);
  const [showNotes, setShowNotes] = useState(false);
  const [showFinish, setShowFinish] = useState(false);
  const [coach, setCoach] = useState(false);
  const endRef = useRef();
  const pendingRef = useRef();
  const inputRef = useRef();
  useEffect(() => { endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }, [session.turn, thinking]);
  useEffect(() => () => clearTimeout(pendingRef.current), []);
  const send = (value, intent) => {
    if (!value.trim() || thinking) return;
    setThinking(true); setText('');
    pendingRef.current = setTimeout(() => { onUpdate(advance(session, scenario, value.trim(), intent)); setThinking(false); inputRef.current?.focus(); }, 500);
  };
  const lastEvent = session.events.at(-1);
  return <div className="training-room"><div className="room-top"><button className="text-link muted" disabled={thinking} onClick={onPause}><ArrowLeft size={16}/>Guardar y salir</button><span><span className="live-dot"/> PRÁCTICA EN CURSO</span><button className="text-link muted" onClick={onHelp}><HelpCircle size={16}/>Cómo funciona</button></div><div className="room-heading"><div><h1>{scenario.title}</h1><p>{scenario.subtitle}</p></div><LevelBadge level={scenario.level}/></div><div className="room-layout"><section className="conversation"><div className="conversation-top"><Avatar person={scenario.person}/><div><h3>{scenario.person.name}</h3><p>{scenario.person.role}</p></div><span className="person-style">{scenario.person.style}</span></div><div className="chat-messages" role="log" aria-label="Conversación de práctica" aria-live="polite">{session.messages.map((m, i) => m.role === 'system' ? <div className="system-message" key={i}>{m.text}</div> : <div className={`message message-${m.role}`} key={i}>{m.role === 'person' && <Avatar person={scenario.person} size="tiny"/>}<div><span className="message-name">{m.role === 'user' ? 'Tú' : scenario.person.name.split(' ')[0]}<span>{m.turn ? `Intervención ${m.turn}` : 'Inicio de la conversación'}</span></span><div className="message-bubble">{m.text.split('\n').map((p, j) => <p key={j}>{p}</p>)}</div></div>{m.role === 'user' && <span className="self-avatar">Tú</span>}</div>)}{thinking && <div className="typing"><span/><span/><span/><span className="sr-only">Preparando la respuesta…</span></div>}<div ref={endRef}/></div>
      {lastEvent?.unexpected && <div className="unexpected-note"><Sparkles size={15}/><span>El contexto cambió. Revisa la nueva información antes de responder.</span></div>}
      <div className="composer"><div className="suggestion-heading"><span><Lightbulb size={14}/> Una forma de continuar</span><span>o escribe con tus palabras</span></div><div className="suggested-responses">{suggestions(session, scenario).map((s, i) => <button disabled={thinking} onClick={() => send(s.text, s.intent)} key={`${session.turn}-${i}`}><span>{String(i + 1).padStart(2, '0')}</span><div><b>{s.label}</b><p>{s.text}</p></div><ArrowUpRight size={15}/></button>)}</div><form onSubmit={e => { e.preventDefault(); send(text); }}><label className="sr-only" htmlFor="intervention">Tu intervención</label><textarea id="intervention" ref={inputRef} value={text} onChange={e => setText(e.target.value)} maxLength={1600} placeholder="¿Qué le dirías? Encuentra tus propias palabras…" rows={2} disabled={thinking} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(text); } }}/><button className="send-button" type="submit" disabled={!text.trim() || thinking} aria-label="Enviar intervención"><Send size={18}/></button></form><div className="composer-footer"><span>Enter para enviar · Shift + Enter para otra línea</span><span>{text.length}/1600</span></div></div>
      </section><aside className="room-aside"><div className="session-objective"><span className="section-eyebrow"><Target size={14}/>TU NORTE</span><h3>Lo que quieres conseguir</h3><p>{scenario.objective}</p><button className="text-link" onClick={() => setShowNotes(!showNotes)}><NotebookPen size={15}/>{showNotes ? 'Ocultar preparación' : 'Ver mi preparación'}<ChevronDown size={14}/></button>{showNotes && <div className="session-notes"><h4>Tu contexto</h4><p>{scenario.context}</p>{[['objective', 'Mi objetivo'], ['alternative', 'Mi alternativa'], ['limit', 'Mi límite']].map(([key, label]) => <div key={key}><h4>{label}</h4><p>{session.preparation[key] || 'No lo anotaste antes de comenzar.'}</p></div>)}<h4>Restricciones</h4><ul>{scenario.constraints.map(c => <li key={c}>{c}</li>)}</ul></div>}</div><div className="climate-card"><span className="section-eyebrow">EL PULSO DE LA CONVERSACIÓN</span><h3>{session.trust >= 70 ? 'Hay espacio para construir' : session.trust < 35 ? 'La relación necesita atención' : 'Se están conociendo'}</h3><p>Las decisiones influyen en la disposición de tu interlocutor.</p><div className="climate-label"><span>Apertura</span><b>{session.trust >= 70 ? 'Alta' : session.trust < 35 ? 'Baja' : 'En desarrollo'}</b></div><div className="climate-track"><span style={{ width: `${session.trust}%` }}/></div><div className="climate-label"><span>Tensión</span><b>{session.tension > 50 ? 'Elevada' : session.tension > 25 ? 'Moderada' : 'Baja'}</b></div><div className="climate-track tension"><span style={{ width: `${session.tension}%` }}/></div><p className="climate-footnote">Señales del simulador, no una lectura psicológica.</p></div>
      {session.offer && <div className="pending-offer"><Handshake size={19}/><h3>Propuesta sobre la mesa</h3><p>{session.offer.text}</p><span>Pendiente de tu confirmación</span></div>}
      <button className={`coach-toggle ${coach ? 'active' : ''}`} onClick={() => setCoach(!coach)}><Sparkles size={17}/>Pista de entrenamiento<ChevronDown size={15}/></button>{coach && <div className="coach-card"><p>{lastEvent?.insight || 'Empieza por comprender qué necesita la otra parte. Una pregunta abierta puede darte más información que una propuesta inmediata.'}</p></div>}<div className="session-bottom"><span><MessagesSquare size={15}/>{session.turn} de 12 intervenciones</span><button className="button secondary" disabled={thinking || session.turn === 0} onClick={() => setShowFinish(true)}><Flag size={15}/>Finalizar y analizar</button><p>Puedes terminar sin acuerdo. Saber cuándo parar también se entrena.</p></div></aside></div>
      {showFinish && <Modal onClose={() => setShowFinish(false)} className="confirm-modal" titleId="finish-title"><span className="modal-symbol"><Flag size={28}/></span><h2 id="finish-title">¿Revisamos esta conversación?</h2><p>{session.offer ? 'Hay una propuesta pendiente, pero aún no está confirmada. Puedes seguir negociando o terminar sin acuerdo y analizar tus decisiones.' : 'El resultado se guardará como una conversación sin acuerdo. También aprenderás de lo que quedó abierto.'}</p><div className="confirm-actions"><button className="button secondary" onClick={() => setShowFinish(false)}>Seguir conversando</button><button className="button primary" onClick={() => onUpdate(finishSession(session))}>Ver mi análisis<ArrowRight size={15}/></button></div></Modal>}
  </div>;
}

function Review({ session, scenario, onRetry, onRewind, onProgress, onLesson }) {
  const analysis = evaluate(session);
  const [tab, setTab] = useState('analysis');
  const [confirmRewind, setConfirmRewind] = useState(null);
  const [expanded, setExpanded] = useState(null);
  const good = session.events.filter(e => e.effects.length >= 2).slice(0, 3);
  const missed = [!session.discovered && 'No exploraste los intereses antes de buscar una solución.', !session.heard && 'Faltó comprobar cómo estaba viviendo la situación la otra persona.', !session.conditional && 'Podías vincular tus concesiones a condiciones explícitas.', !session.bounded && 'Tus límites no quedaron expresados de forma observable.', !analysis.preparation && 'No dejaste un objetivo, una alternativa ni un límite en tu preparación.'].filter(Boolean);
  const nextLesson = lessons.find(l => l.skill === analysis.weakest[0][0]) || lessons[0];
  const outcome = session.agreed ? 'Un acuerdo para seguir construyendo' : session.reason === 'relationship' ? 'La tensión cerró la conversación' : 'Una conversación con asuntos abiertos';
  return <><div className="review-top"><button className="text-link muted" onClick={onProgress}><ArrowLeft size={15}/>Mi progreso</button><button className="button secondary compact" onClick={() => downloadFile(`pacto-${scenario.id}-analisis.json`, JSON.stringify({ scenario: scenario.title, session, analysis: { scores: analysis.scores, average: analysis.average } }, null, 2))}><Download size={15}/>Exportar análisis</button></div><div className="page-heading"><div><div className="eyebrow">CADA CONVERSACIÓN DEJA UN APRENDIZAJE</div><h1>Hagamos una pausa para aprender<span className="purple-text">.</span></h1><p>{scenario.title} · {session.turn} {session.turn === 1 ? 'intervención' : 'intervenciones'} · {dateLabel(session.finishedAt, { day: 'numeric', month: 'long' })}</p></div></div><section className={`outcome-banner ${session.agreed ? 'agreed' : ''}`}><span className="outcome-icon">{session.agreed ? <Handshake size={31}/> : <Compass size={31}/>}</span><div><span className="section-eyebrow">{session.agreed ? 'ACUERDO CONFIRMADO' : 'SIN ACUERDO CONFIRMADO'}</span><h2>{outcome}</h2><p>{session.agreed ? session.offer.text : session.reason === 'relationship' ? 'Las descalificaciones deterioraron la confianza. Una pausa y una reparación pueden abrir una conversación diferente.' : session.offer ? `Quedó pendiente de confirmar: ${session.offer.text}.` : 'Todavía faltaba convertir los intereses en una propuesta concreta y viable.'}</p></div></section><div className="review-tabs"><button className={tab === 'analysis' ? 'active' : ''} onClick={() => setTab('analysis')}><Sparkles size={16}/>Tu análisis</button><button className={tab === 'conversation' ? 'active' : ''} onClick={() => setTab('conversation')}><MessagesSquare size={16}/>Conversación y alternativas</button></div>
    {tab === 'analysis' ? <div className="review-layout"><div><section className="review-panel"><h2>Lo que pusiste en práctica</h2><p className="muted">Una lectura orientativa basada en tus decisiones observables.</p><div className="skills-bars">{skills.map(([key, label]) => <button className="skill-row" key={key} onClick={() => setExpanded(expanded === key ? null : key)} aria-expanded={expanded === key}><div className="skill-row-top"><span>{label}<Info size={12}/></span><b>{analysis.scores[key]}<span>/100</span></b></div><div className="skill-track"><span style={{ width: `${analysis.scores[key]}%` }}/></div>{expanded === key && <div className="skill-evidence"><p>{skillDescriptions[key]}</p><p>{key === 'preparation' ? `${analysis.preparation} de 3 notas con contenido antes de comenzar.` : key === 'agreement' ? session.agreed ? 'Aceptaste una propuesta con condiciones conocidas.' : 'No hubo confirmación de un acuerdo.' : key === 'emotion' ? `${analysis.pressure} intervenciones con descalificaciones; ${analysis.evidence[key].length} con señales de respeto o reparación. La ausencia de descalificaciones no permite medir tus emociones internas.` : analysis.evidence[key].length ? `Señales en las intervenciones ${analysis.evidence[key].map(e => e.turn).join(', ')}.` : 'No hubo una señal explícita de esta habilidad. Eso no significa que no la tengas.'}</p></div>}</button>)}</div><div className="analysis-disclaimer"><Info size={15}/><p>Estas señales ayudan a reflexionar, no son un diagnóstico ni una evaluación profesional. El motor local reconoce intenciones y puede pasar por alto matices del texto libre.</p></div></section><section className="review-panel"><h2>Qué funcionó y por qué</h2>{good.length ? good.map(e => <div className="evidence-item" key={e.turn}><span><Check size={16}/></span><div><h4>{intentLabels[e.intent]} <small>· Intervención {e.turn}</small></h4><blockquote>«{e.text}»</blockquote><p>{e.insight}</p></div></div>) : <p className="muted">Esta conversación aún no dejó señales suficientes de exploración, escucha o intercambios. Puedes volver al primer turno y probar una pregunta abierta.</p>}</section><section className="review-panel"><h2>Oportunidades y riesgos</h2>{missed.length ? <ul className="opportunity-list">{missed.map(m => <li key={m}><ArrowUpRight size={17}/>{m}</li>)}</ul> : <p>Exploraste intereses, escuchaste, expresaste límites y condicionaste tus intercambios. Tu siguiente reto es comprobar estos comportamientos sin apoyarte en las sugerencias.</p>}{session.events.filter(e => e.risk).map(e => <div className="risk-note" key={e.turn}><AlertCircle size={18}/><p>Intervención {e.turn}: {e.risk}</p></div>)}{analysis.pressure > 0 && <div className="risk-note"><AlertCircle size={18}/><p>La presión personal redujo la confianza y retiró ofertas. Repara el impacto antes de volver a las condiciones.</p></div>}{session.agreed && session.offer.amount && scenario.target && <div className="risk-note neutral"><Info size={18}/><p>La cifra acordada fue <b>${session.offer.amount.toLocaleString('es-CO')} {scenario.unit}</b>, frente a tu referencia de ${scenario.target.toLocaleString('es-CO')}. Evalúa también las condiciones complementarias y tu alternativa; conseguir un sí no demuestra por sí solo que el resultado te convenga.</p></div>}</section></div><aside><section className="review-next"><div className="insight-icon"><SproutIcon/></div><span className="section-eyebrow">TU SIGUIENTE PASO</span><h3>{analysis.weakest[0][1]} con más intención</h3><p>En la siguiente conversación, céntrate en una habilidad a la vez. Empieza por una herramienta concreta.</p><button className="button secondary" onClick={() => onLesson(nextLesson)}>Abrir la lección<ArrowUpRight size={15}/></button></section><section className="retry-card"><RotateCcw size={24}/><h3>¿Y si lo intentas de otra manera?</h3><p>Vuelve al caso con una estrategia nueva. Cada intento se guarda por separado.</p><button className="button primary" onClick={onRetry}>Volver a practicar<ArrowRight size={15}/></button><button className="text-link" onClick={() => setTab('conversation')}>Explorar un momento concreto</button></section></aside></div> : <section className="review-panel conversation-review"><h2>Los momentos que construyeron el resultado</h2><p className="muted">Revisa cada decisión y prueba una alternativa desde el mismo punto. Tu intento original se conserva.</p><div className="opening-review"><b>{scenario.person.name}</b><p>{scenario.opening}</p></div>{session.events.map(e => { const feedback = feedbackFor(e, scenario); return <article className="turn-review" key={e.turn}><div className="turn-review-heading"><span>INTERVENCIÓN {e.turn}</span><span>{intentLabels[e.intent]}</span></div><h4>Tu intervención</h4><blockquote>«{e.text}»</blockquote><h4>La respuesta de {scenario.person.name.split(' ')[0]}</h4><p>{e.reply}</p><div className="turn-learning"><Lightbulb size={19}/><div><h4>{feedback.title}</h4><p>{e.insight}</p><span>UNA ALTERNATIVA PARA EXPLORAR</span><p>«{feedback.better}»</p></div></div><button className="button secondary compact" onClick={() => setConfirmRewind(e.turn)}><RotateCcw size={14}/>Probar otra respuesta desde aquí</button></article>; })}</section>}
    {confirmRewind && <Modal onClose={() => setConfirmRewind(null)} className="confirm-modal" titleId="rewind-title"><span className="modal-symbol"><RotateCcw size={28}/></span><h2 id="rewind-title">Una decisión, otro camino</h2><p>Volverás al momento anterior a la intervención {confirmRewind}. El intento original se conserva.{/* An active session is always preserved by the caller. */} Si hay una práctica en pausa con intervenciones, se guardará como finalizada sin acuerdo.</p><div className="confirm-actions"><button className="button secondary" onClick={() => setConfirmRewind(null)}>Cancelar</button><button className="button primary" onClick={() => onRewind(confirmRewind)}>Explorar alternativa<ArrowRight size={15}/></button></div></Modal>}
    <Footer/></>;
}

function Progress({ history, evaluations, averages, weeklyCount, goal, onPractice, onReview, onLesson, weakest }) {
  const [historyFilter, setHistoryFilter] = useState('all');
  const shown = history.slice().reverse().filter(s => historyFilter === 'all' || (historyFilter === 'agreed' ? s.agreed : !s.agreed));
  const nextLesson = lessons.find(l => l.skill === weakest[0]) || lessons[0];
  return <><div className="page-heading"><div><div className="eyebrow">LO QUE PRACTICAS, CRECE</div><h1>Tu evolución, con perspectiva<span className="purple-text">.</span></h1><p>Reconoce patrones, descubre fortalezas y decide qué quieres entrenar después.</p></div></div>{!history.length ? <><EmptyState icon={ChartNoAxesCombined} title="Tu recorrido empieza con una conversación" text="Al terminar tu primera práctica verás las habilidades que utilizaste, tus oportunidades de mejora y un historial para comparar estrategias." action="Empezar mi recorrido" onAction={onPractice}/><div className="progress-principles">{[['Observa', 'Qué preguntas, cómo escuchas y qué propones.'], ['Reflexiona', 'Qué decisiones ayudaron y cuáles puedes cambiar.'], ['Vuelve a probar', 'Experimenta sin consecuencias fuera de la práctica.']].map(([title, text], i) => <div key={title}><span>0{i + 1}</span><h3>{title}</h3><p>{text}</p></div>)}</div></> : <><div className="progress-stats"><StatCard icon={MessagesSquare} color="purple" value={history.length} label="Prácticas completadas" detail={`${new Set(history.map(s => s.scenarioId)).size} escenarios explorados`}/><StatCard icon={Handshake} color="mint" value={history.filter(s => s.agreed).length} label="Acuerdos confirmados" detail="Un acuerdo también necesita ser sostenible"/><StatCard icon={Target} color="peach" value={`${weeklyCount} / ${goal}`} label="Prácticas esta semana" detail="Tu objetivo se ajusta en Configuración"/></div><div className="progress-panels"><section className="review-panel"><h2>Tu mapa de habilidades</h2><p className="muted">Promedio de señales observadas en tus prácticas.</p><Radar averages={averages}/><p className="small-text muted">Un valor bajo indica poca evidencia explícita, no falta de capacidad. Compara intentos del mismo caso para obtener más contexto.</p></section><section className="review-panel evolution-panel"><h2>Lo que cuenta tu recorrido</h2><p className="muted">Señales orientativas de las últimas {Math.min(8, history.length)} prácticas.</p><TrendChart evaluations={evaluations.slice(-8)}/><div className="recommendation"><span className="lesson-icon"><Target size={21}/></span><div><span className="section-eyebrow">UN FOCO PARA TU PRÓXIMA PRÁCTICA</span><h3>{weakest[1]}</h3><p>{nextLesson.short}</p><button className="text-link" onClick={() => onLesson(nextLesson)}>Explorar la herramienta<ArrowRight size={14}/></button></div></div></section></div><section className="review-panel history-panel"><div className="section-heading"><div><h2>Tu historial de conversaciones</h2><p>Vuelve a tus decisiones y explora otros caminos.</p></div><select aria-label="Filtrar historial" value={historyFilter} onChange={e => setHistoryFilter(e.target.value)}><option value="all">Todos los desenlaces</option><option value="agreed">Con acuerdo</option><option value="open">Sin acuerdo</option></select></div>{shown.length ? shown.map(s => { const scenario = scenarios.find(c => c.id === s.scenarioId); const Icon = iconMap[scenario.icon]; return <button className="history-row" key={s.id} onClick={() => onReview(s)}><span className={`stat-icon ${scenario.color}`}><Icon size={20}/></span><div><h3>{scenario.title}</h3><p>{dateLabel(s.finishedAt)} · {s.turn} intervenciones</p></div><span className={`outcome-chip ${s.agreed ? 'success' : ''}`}>{s.agreed ? 'Acuerdo confirmado' : 'Sin acuerdo'}</span><span className="history-review">Ver análisis<ArrowUpRight size={15}/></span></button>; }) : <p className="muted">No hay prácticas con este desenlace.</p>}</section></>}<Footer/></>;
}

function Radar({ averages }) {
  const center = 170, radius = 112;
  const point = (i, scale) => { const angle = i * 2 * Math.PI / skills.length - Math.PI / 2; return [center + Math.cos(angle) * radius * scale, center + Math.sin(angle) * radius * scale]; };
  return <svg className="radar-chart" viewBox="0 0 340 340" role="img" aria-label={`Mapa de habilidades: ${skills.map(([k, l]) => `${l} ${averages[k]} de 100`).join(', ')}`}>{[.25, .5, .75, 1].map(scale => <polygon key={scale} points={skills.map((_, i) => point(i, scale).join(',')).join(' ')} fill={scale === 1 ? '#fbfafc' : 'none'} stroke="#e7e2ef"/>).reverse()}{skills.map(([key, label], i) => <g key={key}><line x1={center} y1={center} x2={point(i, 1)[0]} y2={point(i, 1)[1]} stroke="#e7e2ef"/><text x={point(i, 1.27)[0]} y={point(i, 1.27)[1]} textAnchor="middle" dominantBaseline="middle">{label}</text></g>)}<polygon points={skills.map(([key], i) => point(i, averages[key] / 100).join(',')).join(' ')} fill="#9a83e1" fillOpacity=".24" stroke="#8064cf" strokeWidth="2"/>{skills.map(([key], i) => <circle key={key} cx={point(i, averages[key] / 100)[0]} cy={point(i, averages[key] / 100)[1]} r="3" fill="#8064cf"/>)}</svg>;
}

function TrendChart({ evaluations }) {
  const width = 420, height = 160, pad = 24;
  const points = evaluations.map((e, i) => [pad + (evaluations.length === 1 ? (width - pad * 2) / 2 : i / (evaluations.length - 1) * (width - pad * 2)), height - pad - e.average / 100 * (height - pad * 2)]);
  return <div className="trend-wrap"><svg viewBox={`0 0 ${width} ${height}`} role="img" aria-label={evaluations.map((e, i) => `Práctica ${i + 1}: ${e.average} de 100 señales orientativas`).join('; ')}>{[25, 50, 75].map(y => <g key={y}><line x1={pad} y1={height - pad - y / 100 * (height - pad * 2)} x2={width - pad} y2={height - pad - y / 100 * (height - pad * 2)} stroke="#ece8f2" strokeDasharray="4 4"/><text x="0" y={height - pad - y / 100 * (height - pad * 2) + 3}>{y}</text></g>)}{points.length > 1 && <polyline points={points.map(p => p.join(',')).join(' ')} fill="none" stroke="#8c72d8" strokeWidth="2.5"/>}{points.map(([x, y], i) => <g key={i}><circle cx={x} cy={y} r="5" fill="#8c72d8" stroke="white" strokeWidth="2"/><text x={x} y={height - 4} textAnchor="middle">{i + 1}</text></g>)}</svg><p className="small-text muted">{evaluations.length === 1 ? 'Una primera referencia. La evolución aparecerá con nuevas prácticas.' : 'Promedio orientativo por práctica. Los casos y niveles pueden variar.'}</p></div>;
}

function SettingsModal({ store, onUpdate, onReset, onClose, onToast }) {
  const [name, setName] = useState(store.name);
  const [goal, setGoal] = useState(store.weeklyGoal);
  const [clear, setClear] = useState(false);
  return <Modal onClose={onClose} className="settings-modal" titleId="settings-title"><span className="eyebrow">A TU MEDIDA</span><h2 id="settings-title">Tu espacio personal</h2><p className="muted">Haz que practicar forme parte de tu rutina.</p><form onSubmit={e => { e.preventDefault(); onUpdate(prev => ({ ...prev, name: name.trim().slice(0, 32), weeklyGoal: goal })); onToast('Preferencias guardadas. Este espacio es tuyo.'); onClose(); }}><label>¿Cómo te llamamos?<input required maxLength={32} value={name} onChange={e => setName(e.target.value)} placeholder="Tu nombre"/></label><label>Tu objetivo semanal<select value={goal} onChange={e => setGoal(Number(e.target.value))}>{[1, 2, 3, 4, 5, 7].map(n => <option value={n} key={n}>{n} {n === 1 ? 'práctica' : 'prácticas'} por semana</option>)}</select></label><p className="small-text muted">Tus conversaciones y preferencias se guardan solo en este navegador. No se envían a un servidor ni se sincronizan entre dispositivos.</p><button type="submit" disabled={!name.trim()} className="button primary">Guardar preferencias<Check size={16}/></button></form><div className="settings-data"><h3>Tus datos, bajo tu control</h3><button className="button secondary" onClick={() => downloadFile('pacto-mi-progreso.json', JSON.stringify(store, null, 2))}><Download size={16}/>Exportar mi progreso</button><button className="text-link danger" onClick={() => setClear(true)}><Trash2 size={15}/>Borrar todos mis datos</button>{clear && <div className="delete-confirm"><p>Se borrarán el historial, la conversación en pausa y las lecciones leídas de este navegador. Puedes exportarlos antes.</p><button className="button danger-button" onClick={() => { onReset(); onToast('Datos locales borrados. Puedes empezar un nuevo recorrido.'); onClose(); }}>Sí, borrar mis datos</button><button className="text-link" onClick={() => setClear(false)}>Conservar mis datos</button></div>}</div></Modal>;
}

function HelpModal({ onClose }) {
  return <Modal onClose={onClose} className="help-modal" titleId="help-title"><span className="modal-symbol"><HeartHandshake size={31}/></span><span className="eyebrow">BIENVENIDO A PACTO</span><h2 id="help-title">Un espacio para practicar de verdad</h2><p>Prepara tu estrategia, conversa y vuelve a mirar tus decisiones con perspectiva.</p><ol className="lesson-steps"><li><span>1</span><div><b>Elige y prepara</b><p>Revisa los objetivos, las restricciones y los intereses. Anota tu alternativa y tu límite.</p></div></li><li><span>2</span><div><b>Entra en la conversación</b><p>Usa las sugerencias o escribe con tus palabras. Las preguntas, la escucha, las propuestas y la presión cambian la apertura y las respuestas del personaje.</p></div></li><li><span>3</span><div><b>Aprende y prueba otra vía</b><p>Recibe una revisión con evidencias de tus turnos. Puedes volver a un momento concreto sin perder el intento original.</p></div></li></ol><div className="help-transparency"><Info size={20}/><div><h3>Cómo funciona esta versión</h3><p>El simulador utiliza un motor local de intenciones y estados, con respuestas redactadas para cada caso. No utiliza inteligencia artificial generativa ni interpreta todos los matices del texto libre. No necesitas claves ni una cuenta. Las puntuaciones son orientativas y tu historial se guarda solo en este navegador.</p></div></div><button className="button primary" onClick={onClose}>Vamos a practicar<ArrowRight size={16}/></button></Modal>;
}

export default App;
